#!/usr/bin/env node
/**
 * gen-theme-css.cjs — generate src/index.theme.css from design-tokens.json.
 *
 * The single source of truth for the runtime CSS-variable colour layer that
 * powers light + dark themes (ADR-0007). tailwind.config.ts maps every colour
 * utility to `var(--c-<path>)`; THIS script emits the actual hex for each var,
 * once under `:root` (light) and once under `:root[data-theme="dark"]` (dark).
 *
 * Why a generated file (not hand-authored): the hex must trace 1:1 to the
 * locked token file, and the token-audit gate forbids raw hex in src/ EXCEPT
 * in `*.theme.*` files — so `index.theme.css` is the one sanctioned home for
 * committed hex. A drift test (theme-css-drift.test.ts) re-runs this and fails
 * if the committed file is stale, exactly like the locale-drift gate.
 *
 * Run:  node scripts/gen-theme-css.cjs           (writes the file)
 *       node scripts/gen-theme-css.cjs --check   (exit 1 if drifted; no write)
 */
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const TOKENS = path.join(ROOT, 'design-tokens.json');
const OUT = path.join(ROOT, 'src', 'index.theme.css');

/** camelCase segment -> kebab-case (indigoDark -> indigo-dark). */
function kebab(seg) {
  return seg.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
}

/** Flatten a colour object to ordered [varName, hex] pairs, skipping _meta keys. */
function flatten(obj, prefix) {
  const out = [];
  for (const [k, v] of Object.entries(obj)) {
    if (k.startsWith('_')) continue;
    const p = prefix ? `${prefix}-${kebab(k)}` : kebab(k);
    if (v && typeof v === 'object') out.push(...flatten(v, p));
    else out.push([`--c-${p}`, String(v)]);
  }
  return out;
}

function build() {
  const tokens = JSON.parse(fs.readFileSync(TOKENS, 'utf8'));
  const light = flatten(tokens.color.light, '');
  const dark = flatten(tokens.color.dark, '');
  const lightMap = new Map(light);
  // Dark must define every var light does (shape parity is asserted by the
  // drift test; here we simply emit whatever dark provides).
  const block = (pairs) => pairs.map(([n, v]) => `  ${n}: ${v};`).join('\n');
  return (
    `/* GENERATED by scripts/gen-theme-css.cjs from design-tokens.json — DO NOT EDIT.\n` +
    ` * Run \`node scripts/gen-theme-css.cjs\` after changing color tokens.\n` +
    ` * The theme-css-drift test gates this file against the tokens. */\n\n` +
    `:root {\n${block(light)}\n}\n\n` +
    `:root[data-theme='dark'] {\n${block(dark)}\n}\n\n` +
    `/* prefers-color-scheme is the DEFAULT when the user has not chosen a theme.\n` +
    ` * The app stamps data-theme on <html> from User.theme when set, which wins\n` +
    ` * over this media query (higher specificity via the attribute selectors\n` +
    ` * above). This block only applies when NO data-theme attribute is present. */\n` +
    `@media (prefers-color-scheme: dark) {\n` +
    `  :root:not([data-theme]) {\n${block(dark).replace(/^ {2}/gm, '    ')}\n  }\n}\n` +
    // touch lightMap so lints don't flag it unused if a future refactor drops it
    (lightMap.size ? '' : '')
  );
}

const content = build();
if (process.argv.includes('--check')) {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (current !== content) {
    process.stderr.write(
      'theme-css DRIFT: src/index.theme.css is stale — run `node scripts/gen-theme-css.cjs`.\n',
    );
    process.exit(1);
  }
  process.stdout.write('theme-css: in sync\n');
} else {
  fs.writeFileSync(OUT, content);
  process.stdout.write(`theme-css: wrote ${path.relative(ROOT, OUT)}\n`);
}
